      if (lookahead == '-') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(78); }
      if (lookahead == '.') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(125); }
      if (lookahead == '/') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(113); }
